# osm_normalization.py -- address normalization rules and OPL reading used to build the OpenStreetMap-
# derived index osm_num_rue v1 (ODbL 4.6(b) method). Extracted verbatim from the code that reads the index.
import re
import subprocess


ABR = {"STREET": "ST", "AVENUE": "AVE", "AV": "AVE", "DRIVE": "DR", "ROAD": "RD", "BOULEVARD": "BLVD",
       "LANE": "LN", "COURT": "CT", "PLACE": "PL", "TERRACE": "TER", "CIRCLE": "CIR", "PARKWAY": "PKWY",
       "HIGHWAY": "HWY", "TRAIL": "TRL", "SQUARE": "SQ", "EXPRESSWAY": "EXPY", "FREEWAY": "FWY",
       "NORTH": "N", "SOUTH": "S", "EAST": "E", "WEST": "W", "NORTHEAST": "NE", "NORTHWEST": "NW",
       "SOUTHEAST": "SE", "SOUTHWEST": "SW", "MOUNT": "MT", "SAINT": "ST", "CROSSING": "XING",
       "POINT": "PT", "HEIGHTS": "HTS", "ALLEY": "ALY", "LOOP": "LOOP", "WAY": "WAY"}


def norm(s):
    return " ".join(re.sub(r"[^A-Z0-9 ]", " ", (s or "").upper()).split())


def norm_street(s):
    return " ".join(ABR.get(t, t) for t in norm(s).split())


def opl_unesc(s):
    return re.sub(r"%([0-9a-fA-F]+)%", lambda m: chr(int(m[1], 16)), s)


def opl_parse(line):
    """OPL -> (type, id, tags, x, y, refs, membres)."""
    champs = line.rstrip("\n").split(" ")
    t, oid = champs[0][0], int(champs[0][1:])
    tags, x, y, refs, mem = {}, None, None, [], []
    for c in champs[1:]:
        if not c:
            continue
        k, v = c[0], c[1:]
        if k == "T" and v:
            for kv in v.split(","):
                a, _, b = kv.partition("=")
                tags[opl_unesc(a)] = opl_unesc(b)
        elif k == "x" and v:
            x = float(v)
        elif k == "y" and v:
            y = float(v)
        elif k == "N" and v:
            refs = [int(r[1:]) for r in v.split(",")]
        elif k == "M" and v:
            mem = [(m[0], int(m[1:].split("@")[0])) for m in v.split(",")]
    return t, oid, tags, x, y, refs, mem


def osm_returned(tags):
    return {"number": norm(tags.get("addr:housenumber", "")), "street": norm_street(tags.get("addr:street", "")),
            "city": norm(tags.get("addr:city", "")), "state": norm(tags.get("addr:state", "")),
            "zip": tags.get("addr:postcode", "")[:5]}


def osm_addr_lines(pbf):
    """Lecteur FICHIER : tous les objets portant addr:housenumber (OPL, references omises)."""
    return _flux(["osmium", "tags-filter", "-R", "-f", "opl,add_metadata=false", "-o", "-", pbf,
                  "nwr/addr:housenumber"])


def _flux(cmd):
    p = subprocess.Popen(cmd, stdout=subprocess.PIPE, text=True, bufsize=1 << 20)
    for line in p.stdout:
        yield line
    if p.wait() != 0:
        raise RuntimeError("OSM_READER_FAILED : %s rc %s" % (cmd[1], p.returncode))
